                ->transform.position.y = 0.0f;
            ((AttachmentSample*)((char*)primary_samples + tail_sample_offset))
                ->transform.position.z = z;
            ((AttachmentSample*)((char*)primary_samples + tail_sample_offset))
                ->delta_length = 1.0f;

