void cRPath::initialize_toad_path_template_pair(
    bool turn_left, char* texture_a, char* texture_b, char* vertical_texture)
{
    int lead_count;
    int tail_count;
    float start_x;
    float turn_sign;
    int i;

    kind = PATH_TEMPLATE_KIND_TURNUNDER_TOAD_FAMILY;
    is_mirrored_x = 0;
    side_exit_mode = 0;
