    if (turn_left) {
        start_x = -2.0f;
        turn_sign = -1.0f;
        lead_count = 1;
        tail_count = 3;
    } else {
        start_x = 2.0f;
        turn_sign = 1.0f;
        lead_count = 2;
        tail_count = 1;
