                            facequads[face_offset].texture_ref =
                                g_texture_refs.Add(texture_a, 0, 0);
                        else
                            facequads[face_offset].texture_ref =
                                g_texture_refs.Add(texture_a, 0, 0);
                    } else {
                        facequads[face_offset].header_word = 0;
                        facequads[face_offset].vertex_0 = row * ((unsigned short)path->width_cells + 1) + column + 1;
                        facequads[face_offset].vertex_1 = column + row * ((unsigned short)path->width_cells + 1);
                        facequads[face_offset].vertex_2 = column + (row + 1) * ((unsigned short)path->width_cells + 1);
                        facequads[face_offset].vertex_3 = (row + 1) * ((unsigned short)path->width_cells + 1) + column + 1;
                        if ((column ^ row) & 1)
                            facequads[face_offset].texture_ref =
                                g_texture_refs.Add(texture_b, 0, 0);
                        else
                            facequads[face_offset].texture_ref =
                                g_texture_refs.Add(texture_b, 0, 0);
                    }
                    if (face_index == 0) {
                        facequads[face_offset].uv[0].u = u0;
                        facequads[face_offset].uv[0].v = v0;
                        facequads[face_offset].uv[1].u = u1;
                        facequads[face_offset].uv[1].v = v0;
                        facequads[face_offset].uv[2].u = u1;
                        facequads[face_offset].uv[2].v = v1;
                        facequads[face_offset].uv[3].u = u0;
                        facequads[face_offset].uv[3].v = v1;
                    } else {
                        facequads[face_offset].uv[0].u = u1;
                        facequads[face_offset].uv[0].v = v0;
                        facequads[face_offset].uv[1].u = u0;
                        facequads[face_offset].uv[1].v = v0;
                        facequads[face_offset].uv[2].u = u0;
                        facequads[face_offset].uv[2].v = v1;
                        facequads[face_offset].uv[3].u = u1;
                        facequads[face_offset].uv[3].v = v1;
                    }
                }
                ++column;
            } while (column < path->width_cells);
        }
    }
}

void cRPath::initialize_toad_path_template_pair(
    bool turn_left, char* texture_a, char* texture_b, char* vertical_texture)
{
    int lead_count;
    int tail_count;
    float start_x;
    float turn_sign;
    int i;

    kind = PATH_TEMPLATE_KIND_TURNUNDER_TOAD_FAMILY;
    is_mirrored_x = 0;
    side_exit_mode = 0;
    width_cells = 4;

    if (turn_left) {
        start_x = -2.0f;
        turn_sign = -1.0f;
        lead_count = 1;
        tail_count = 3;
    } else {
        start_x = 2.0f;
        turn_sign = 1.0f;
        lead_count = 2;
        tail_count = 1;
    }

    width_or_scale = 1.0f;
    segment_count = lead_count + tail_count + 26;
    segment_count_f = (float)segment_count;
    GetNodes();

    has_entry_mesh_transition = 0;
    for (i = 0; i < lead_count; ++i) {
        primary_samples[i].center_x = start_x;
        primary_samples[i].rotation_scalar_98 = 0.0f;
        primary_samples[i].rotation_scalar_94 = 0.0f;
        primary_samples[i].special_scalar = 0.0f;
        primary_samples[i].lateral_scale = 1.0f;
        primary_samples[i].transform.Identity();
        primary_samples[i].transform.position.x = primary_samples[i].center_x;
        float z = (float)i;
        primary_samples[i].transform.position.y = 0.0f;
        primary_samples[i].transform.position.z = z;
        primary_samples[i].delta_length = 1.0f;

        secondary_samples[i].transform.Identity();
        secondary_samples[i].transform.position.x = primary_samples[i].center_x;
        secondary_samples[i].transform.position.y = 0.49000001f;
        secondary_samples[i].transform.position.z = z;
        secondary_samples[i].delta_length = 1.0f;
    }

    for (i = 0; i < tail_count; ++i) {
        int sample_index = lead_count + 26 + i;
        primary_samples[sample_index].center_x = start_x;
        primary_samples[sample_index].rotation_scalar_98 = 0.0f;
        primary_samples[sample_index].rotation_scalar_94 = 0.0f;
        primary_samples[sample_index].special_scalar = 0.0f;
        primary_samples[sample_index].lateral_scale = 1.0f;
        primary_samples[sample_index].transform.Identity();
        float z = (float)sample_index;
        primary_samples[sample_index].transform.position.x =
            primary_samples[sample_index].center_x;
        primary_samples[sample_index].transform.position.y = 0.0f;
        primary_samples[sample_index].transform.position.z = z;
        primary_samples[sample_index].delta_length = 1.0f;

        secondary_samples[sample_index].transform.Identity();
        secondary_samples[sample_index].transform.position.x =
            primary_samples[sample_index].center_x;
        secondary_samples[sample_index].transform.position.y = 0.49000001f;
        secondary_samples[sample_index].transform.position.z = z;
        secondary_samples[sample_index].delta_length = 1.0f;
    }

    for (i = 0; i < 26; ++i) {
        int sample_index = lead_count + i;
        float phase = (float)i * 6.2831855f / 26.0f;
        float angle = (1.0f - Cos(phase)) * 0.5f;
        angle = angle * turn_sign * 3.1415927f * 0.5f;

        primary_samples[sample_index].center_x =
            start_x;
        primary_samples[sample_index].rotation_scalar_98 =
            0.0f;
        primary_samples[sample_index].rotation_scalar_94 =
            0.0f;
        primary_samples[sample_index].special_scalar =
            0.0f;
        primary_samples[sample_index].lateral_scale =
            1.0f;
        primary_samples[sample_index].transform.Identity();
        float turn_x = Sin(angle);
        primary_samples[sample_index].transform.position.x = turn_x + turn_x + start_x;
        primary_samples[sample_index].transform.position.z = (float)(lead_count + i);
        primary_samples[sample_index].transform.position.y = 0.0f;

        primary_samples[sample_index].transform.basis_up = Vector3(0.0f, 1.0f, 0.0f);
        primary_samples[sample_index].transform.basis_forward =
            primary_samples[sample_index].transform.position -
            primary_samples[sample_index - 1].transform.position;
        primary_samples[sample_index].transform.basis_forward.Normalize();
        primary_samples[sample_index].transform.basis_right.Cross(
            primary_samples[sample_index].transform.basis_up,
            primary_samples[sample_index].transform.basis_forward);
        primary_samples[sample_index].transform.RotLocalZ(angle);

        secondary_samples[sample_index].transform =
            primary_samples[sample_index].transform;
        Vector3 lane_offset =
            primary_samples[sample_index].transform.basis_up * 0.49000001f;
        secondary_samples[sample_index].transform.position += lane_offset;
    }

    compute_path_deltas(this);
    build_strip_mesh(this, texture_a, texture_b);
    CalcLengthZ();
}
